// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 balanceBefore = c.getBalance(actor);
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        uint256 balanceAfter = c.getBalance(actor);
        if (ok) {
            assertEq(balanceAfter, 0);
        } else {
            assertEq(balanceAfter, balanceBefore);
        }
        assertTrue(ok ? balanceAfter == 0 : balanceAfter == balanceBefore);
    }
}
